#!/usr/bin/env python3
"""Extract http(s) URLs from Markdown files in the repo and HEAD-check them."""
import re, subprocess, sys, concurrent.futures

files = subprocess.run(
    ["git", "ls-files", "*.md"], capture_output=True, text=True, cwd="."
).stdout.split()
urls: set[str] = set()
pattern = re.compile(r"https?://[^\s)>\]\"'`,;]+")
for f in files:
    try:
        text = open(f, encoding="utf-8").read()
    except OSError:
        continue
    for m in pattern.finditer(text):
        u = m.group(0)
        if u.endswith((".", ",", ":", ";", ")", "]", ">", "'")):
            u = u[:-1]
        urls.add(u)

# group known rate-limitable/github URLs by base? keep simple: HEAD with fallback GET
def check(u: str) -> tuple[str, int | str]:
    for method in ("--head", "-L --get --max-time 15"):
        pass
    out = subprocess.run(
        ["curl", "-s", "-o", "/dev/null", "-w", "%{http_code}",
         "--max-time", "15", "-L", "-A", "Mozilla/5.0 (X11; Linux x86_64) linkcheck",
         u], capture_output=True, text=True)
    try:
        code = int(out.stdout)
    except ValueError:
        code = out.stdout.strip() or "ERR"
    return u, code

with concurrent.futures.ThreadPoolExecutor(max_workers=10) as ex:
    results = list(ex.map(check, sorted(urls)))

bad = [(u, c) for u, c in results if c not in (200, 206, 301, 302, 303, 307, 308, 999)]
print(f"{len(urls)} URLs checked; {len(bad)} non-OK")
for u, c in bad:
    print(f"{c}  {u}")

